import{_ as n,o as s,c as p,ae as e}from"./chunks/framework.Iv6F95cJ.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/java-practice/08 - 管程：并发编程的万能钥匙.md","filePath":"books/java-practice/08 - 管程：并发编程的万能钥匙.md"}'),i={name:"books/java-practice/08 - 管程：并发编程的万能钥匙.md"};function l(t,a,o,c,r,d){return s(),p("div",null,[...a[0]||(a[0]=[e(`<p>并发编程这个技术领域已经发展了半个世纪了，相关的理论和技术纷繁复杂。那有没有一种核心技术可以很方便地解决我们的并发问题呢？这个问题如果让我选择，我一定会选择<strong>管程技术</strong>。Java语言在1.5之前，提供的唯一的并发原语就是管程，而且1.5之后提供的SDK并发包，也是以管程技术为基础的。除此之外，C/C++、C#等高级语言也都支持管程。</p><p>可以这么说，管程就是一把解决并发问题的万能钥匙。</p><h2 id="什么是管程" tabindex="-1">什么是管程 <a class="header-anchor" href="#什么是管程" aria-label="Permalink to &quot;什么是管程&quot;">&amp;ZeroWidthSpace;</a></h2><p>不知道你是否曾思考过这个问题：为什么Java在1.5之前仅仅提供了synchronized关键字及wait()、notify()、notifyAll()这三个看似从天而降的方法？在刚接触Java的时候，我以为它会提供信号量这种编程原语，因为操作系统原理课程告诉我，用信号量能解决所有并发问题，结果我发现不是。后来我找到了原因：Java采用的是管程技术，synchronized关键字及wait()、notify()、notifyAll()这三个方法都是管程的组成部分。而**管程和信号量是等价的，所谓等价指的是用管程能够实现信号量，也能用信号量实现管程。**但是管程更容易使用，所以Java选择了管程。</p><p>管程，对应的英文是Monitor，很多Java领域的同学都喜欢将其翻译成“监视器”，这是直译。操作系统领域一般都翻译成“管程”，这个是意译，而我自己也更倾向于使用“管程”。</p><p>所谓<strong>管程，指的是管理共享变量以及对共享变量的操作过程，让他们支持并发</strong>。翻译为Java领域的语言，就是管理类的成员变量和成员方法，让这个类是线程安全的。那管程是怎么管的呢？</p><h2 id="mesa模型" tabindex="-1">MESA模型 <a class="header-anchor" href="#mesa模型" aria-label="Permalink to &quot;MESA模型&quot;">&amp;ZeroWidthSpace;</a></h2><p>在管程的发展史上，先后出现过三种不同的管程模型，分别是：Hasen模型、Hoare模型和MESA模型。其中，现在广泛应用的是MESA模型，并且Java管程的实现参考的也是MESA模型。所以今天我们重点介绍一下MESA模型。</p><p>在并发编程领域，有两大核心问题：一个是<strong>互斥</strong>，即同一时刻只允许一个线程访问共享资源；另一个是<strong>同步</strong>，即线程之间如何通信、协作。这两大问题，管程都是能够解决的。</p><p>我们先来看看管程是如何解决<strong>互斥</strong>问题的。</p><p>管程解决互斥问题的思路很简单，就是将共享变量及其对共享变量的操作统一封装起来。假如我们要实现一个线程安全的阻塞队列，一个最直观的想法就是：将线程不安全的队列封装起来，对外提供线程安全的操作方法，例如入队操作和出队操作。</p><p>利用管程，可以快速实现这个直观的想法。在下图中，管程X将共享变量queue这个线程不安全的队列和相关的操作入队操作enq()、出队操作deq()都封装起来了；线程A和线程B如果想访问共享变量queue，只能通过调用管程提供的enq()、deq()方法来实现；enq()、deq()保证互斥性，只允许一个线程进入管程。</p><p>不知你有没有发现，管程模型和面向对象高度契合的。估计这也是Java选择管程的原因吧。而我在前面章节介绍的互斥锁用法，其背后的模型其实就是它。</p><p><img src="https://static001.geekbang.org/resource/image/59/c4/592e33c4339c443728cdf82ab3d318c4.png?wh=1142%2A714" alt="" title="管程模型的代码化语义" loading="lazy" referrerpolicy="no-referrer"></p><p>那管程如何解决线程间的<strong>同步</strong>问题呢？</p><p>这个就比较复杂了，不过你可以借鉴一下我们曾经提到过的就医流程，它可以帮助你快速地理解这个问题。为进一步便于你理解，在下面，我展示了一幅MESA管程模型示意图，它详细描述了MESA模型的主要组成部分。</p><p>在管程模型里，共享变量和对共享变量的操作是被封装起来的，图中最外层的框就代表封装的意思。框的上面只有一个入口，并且在入口旁边还有一个入口等待队列。当多个线程同时试图进入管程内部时，只允许一个线程进入，其他线程则在入口等待队列中等待。这个过程类似就医流程的分诊，只允许一个患者就诊，其他患者都在门口等待。</p><p>管程里还引入了条件变量的概念，而且**每个条件变量都对应有一个等待队列，**如下图，条件变量A和条件变量B分别都有自己的等待队列。</p><p><img src="https://static001.geekbang.org/resource/image/83/65/839377608f47e7b3b9c79b8fad144065.png?wh=1142%2A765" alt="" title="MESA管程模型" loading="lazy" referrerpolicy="no-referrer"></p><p>那<strong>条件变量</strong>和<strong>条件变量等待队列</strong>的作用是什么呢？其实就是解决线程同步问题。你可以结合上面提到的阻塞队列的例子加深一下理解（阻塞队列的例子，是用管程来实现线程安全的阻塞队列，这个阻塞队列和管程内部的等待队列没有关系，本文中<strong>一定要注意阻塞队列和等待队列是不同的</strong>）。</p><p>假设有个线程T1执行阻塞队列的出队操作，执行出队操作，需要注意有个前提条件，就是阻塞队列不能是空的（空队列只能出Null值，是不允许的），<strong>阻塞队列不空</strong>这个前提条件对应的就是管程里的条件变量。 如果线程T1进入管程后恰好发现阻塞队列是空的，那怎么办呢？等待啊，去哪里等呢？就去条件变量对应的<strong>等待队列</strong>里面等。此时线程T1就去“队列不空”这个条件变量的等待队列中等待。这个过程类似于大夫发现你要去验个血，于是给你开了个验血的单子，你呢就去验血的队伍里排队。线程T1进入条件变量的等待队列后，是允许其他线程进入管程的。这和你去验血的时候，医生可以给其他患者诊治，道理都是一样的。</p><p>再假设之后另外一个线程T2执行阻塞队列的入队操作，入队操作执行成功之后，<strong>“阻塞队列不空”这个条件对于线程T1来说已经满足了，此时线程T2要通知T1，告诉它需要的条件已经满足了。当线程T1得到通知后，会从等待队列</strong>里面出来，但是出来之后不是马上执行，而是重新进入到<strong>入口等待队列</strong>里面。这个过程类似你验血完，回来找大夫，需要重新分诊。</p><p>条件变量及其等待队列我们讲清楚了，下面再说说wait()、notify()、notifyAll()这三个操作。前面提到线程T1发现“阻塞队列不空”这个条件不满足，需要进到对应的<strong>等待队列</strong>里等待。这个过程就是通过调用wait()来实现的。如果我们用对象A代表“阻塞队列不空”这个条件，那么线程T1需要调用A.wait()。同理当“阻塞队列不空”这个条件满足时，线程T2需要调用A.notify()来通知A等待队列中的一个线程，此时这个等待队列里面只有线程T1。至于notifyAll()这个方法，它可以通知等待队列中的所有线程。</p><p>这里我还是来一段代码再次说明一下吧。下面的代码用管程实现了一个线程安全的阻塞队列（再次强调：这个阻塞队列和管程内部的等待队列没关系，示例代码只是用管程来实现阻塞队列，而不是解释管程内部等待队列的实现原理）。阻塞队列有两个操作分别是入队和出队，这两个方法都是先获取互斥锁，类比管程模型中的入口。</p><ol><li>对于阻塞队列的入队操作，如果阻塞队列已满，就需要等待直到阻塞队列不满，所以这里用了<code>notFull.await();</code>。</li><li>对于阻塞出队操作，如果阻塞队列为空，就需要等待直到阻塞队列不空，所以就用了<code>notEmpty.await();</code>。</li><li>如果入队成功，那么阻塞队列就不空了，就需要通知条件变量：阻塞队列不空<code>notEmpty</code>对应的等待队列。</li><li>如果出队成功，那就阻塞队列就不满了，就需要通知条件变量：阻塞队列不满<code>notFull</code>对应的等待队列。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>public class BlockedQueue&lt;T&gt;{</span></span>
<span class="line"><span>  final Lock lock =</span></span>
<span class="line"><span>    new ReentrantLock();</span></span>
<span class="line"><span>  // 条件变量：队列不满  </span></span>
<span class="line"><span>  final Condition notFull =</span></span>
<span class="line"><span>    lock.newCondition();</span></span>
<span class="line"><span>  // 条件变量：队列不空  </span></span>
<span class="line"><span>  final Condition notEmpty =</span></span>
<span class="line"><span>    lock.newCondition();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  // 入队</span></span>
<span class="line"><span>  void enq(T x) {</span></span>
<span class="line"><span>    lock.lock();</span></span>
<span class="line"><span>    try {</span></span>
<span class="line"><span>      while (队列已满){</span></span>
<span class="line"><span>        // 等待队列不满 </span></span>
<span class="line"><span>        notFull.await();</span></span>
<span class="line"><span>      }  </span></span>
<span class="line"><span>      // 省略入队操作...</span></span>
<span class="line"><span>      //入队后,通知可出队</span></span>
<span class="line"><span>      notEmpty.signal();</span></span>
<span class="line"><span>    }finally {</span></span>
<span class="line"><span>      lock.unlock();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>  // 出队</span></span>
<span class="line"><span>  void deq(){</span></span>
<span class="line"><span>    lock.lock();</span></span>
<span class="line"><span>    try {</span></span>
<span class="line"><span>      while (队列已空){</span></span>
<span class="line"><span>        // 等待队列不空</span></span>
<span class="line"><span>        notEmpty.await();</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>      // 省略出队操作...</span></span>
<span class="line"><span>      //出队后，通知可入队</span></span>
<span class="line"><span>      notFull.signal();</span></span>
<span class="line"><span>    }finally {</span></span>
<span class="line"><span>      lock.unlock();</span></span>
<span class="line"><span>    }  </span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在这段示例代码中，我们用了Java并发包里面的Lock和Condition，如果你看着吃力，也没关系，后面我们还会详细介绍，这个例子只是先让你明白条件变量及其等待队列是怎么回事。需要注意的是：<strong>await()和前面我们提到的wait()语义是一样的；signal()和前面我们提到的notify()语义是一样的</strong>。</p><h2 id="wait-的正确姿势" tabindex="-1">wait()的正确姿势 <a class="header-anchor" href="#wait-的正确姿势" aria-label="Permalink to &quot;wait()的正确姿势&quot;">&amp;ZeroWidthSpace;</a></h2><p>但是有一点，需要再次提醒，对于MESA管程来说，有一个编程范式，就是需要在一个while循环里面调用wait()。<strong>这个是MESA管程特有的</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>while(条件不满足) {</span></span>
<span class="line"><span>  wait();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Hasen模型、Hoare模型和MESA模型的一个核心区别就是当条件满足后，如何通知相关线程。管程要求同一时刻只允许一个线程执行，那当线程T2的操作使线程T1等待的条件满足时，T1和T2究竟谁可以执行呢？</p><ol><li>Hasen模型里面，要求notify()放在代码的最后，这样T2通知完T1后，T2就结束了，然后T1再执行，这样就能保证同一时刻只有一个线程执行。</li><li>Hoare模型里面，T2通知完T1后，T2阻塞，T1马上执行；等T1执行完，再唤醒T2，也能保证同一时刻只有一个线程执行。但是相比Hasen模型，T2多了一次阻塞唤醒操作。</li><li>MESA管程里面，T2通知完T1后，T2还是会接着执行，T1并不立即执行，仅仅是从条件变量的等待队列进到入口等待队列里面。这样做的好处是notify()不用放到代码的最后，T2也没有多余的阻塞唤醒操作。但是也有个副作用，就是当T1再次执行的时候，可能曾经满足的条件，现在已经不满足了，所以需要以循环方式检验条件变量。</li></ol><h2 id="notify-何时可以使用" tabindex="-1">notify()何时可以使用 <a class="header-anchor" href="#notify-何时可以使用" aria-label="Permalink to &quot;notify()何时可以使用&quot;">&amp;ZeroWidthSpace;</a></h2><p>还有一个需要注意的地方，就是notify()和notifyAll()的使用，前面章节，我曾经介绍过，<strong>除非经过深思熟虑，否则尽量使用notifyAll()</strong>。那什么时候可以使用notify()呢？需要满足以下三个条件：</p><ol><li>所有等待线程拥有相同的等待条件；</li><li>所有等待线程被唤醒后，执行相同的操作；</li><li>只需要唤醒一个线程。</li></ol><p>比如上面阻塞队列的例子中，对于“阻塞队列不满”这个条件变量，其等待线程都是在等待“阻塞队列不满”这个条件，反映在代码里就是下面这3行代码。对所有等待线程来说，都是执行这3行代码，<strong>重点是 while 里面的等待条件是完全相同的</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>while (阻塞队列已满){</span></span>
<span class="line"><span>  // 等待队列不满</span></span>
<span class="line"><span>  notFull.await();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>所有等待线程被唤醒后执行的操作也是相同的，都是下面这几行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>// 省略入队操作...</span></span>
<span class="line"><span>// 入队后,通知可出队</span></span>
<span class="line"><span>notEmpty.signal();</span></span></code></pre></div><p>同时也满足第3条，只需要唤醒一个线程。所以上面阻塞队列的代码，使用signal()是可以的。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">&amp;ZeroWidthSpace;</a></h2><p>管程是一个解决并发问题的模型，你可以参考医院就医的流程来加深理解。理解这个模型的重点在于理解条件变量及其等待队列的工作原理。</p><p>Java参考了MESA模型，语言内置的管程（synchronized）对MESA模型进行了精简。MESA模型中，条件变量可以有多个，Java语言内置的管程里只有一个条件变量。具体如下图所示。</p><p><img src="https://static001.geekbang.org/resource/image/57/fa/57e4d94e90226b70be3d57024f5333fa.png?wh=1142%2A714" alt="" title="Java中的管程示意图" loading="lazy" referrerpolicy="no-referrer"></p><p>Java内置的管程方案（synchronized）使用简单，synchronized关键字修饰的代码块，在编译期会自动生成相关加锁和解锁的代码，但是仅支持一个条件变量；而Java SDK并发包实现的管程支持多个条件变量，不过并发包里的锁，需要开发人员自己进行加锁和解锁操作。</p><p>并发编程里两大核心问题——互斥和同步，都可以由管程来帮你解决。学好管程，理论上所有的并发问题你都可以解决，并且很多并发工具类底层都是管程实现的，所以学好管程，就是相当于掌握了一把并发编程的万能钥匙。</p><h2 id="课后思考" tabindex="-1">课后思考 <a class="header-anchor" href="#课后思考" aria-label="Permalink to &quot;课后思考&quot;">&amp;ZeroWidthSpace;</a></h2><p>wait()方法，在Hasen模型和Hoare模型里面，都是没有参数的，而在MESA模型里面，增加了超时参数，你觉得这个参数有必要吗？</p><p>欢迎在留言区与我分享你的想法，也欢迎你在留言区记录你的思考过程。感谢阅读，如果你觉得这篇文章对你有帮助的话，也欢迎把它分享给更多的朋友。 精选留言（15） Geek_be4cec 👍（398） 💬（37）本节说的可能并不好。该篇我看了三遍也没能完全看懂，于是自己搜索java管程相关的技术文章，才大致对管程有了个认知，总结如下： 1.管程是一种概念，任何语言都可以通用。 2.在java中，每个加锁的对象都绑定着一个管程（监视器） 3.线程访问加锁对象，就是去拥有一个监视器的过程。如一个病人去门诊室看医生，医生是共享资源，门锁锁定医生，病人去看医生，就是访问医生这个共享资源，门诊室其实是监视器（管程）。 4.所有线程访问共享资源，都需要先拥有监视器。就像所有病人看病都需要先拥有进入门诊室的资格。 5.监视器至少有两个等待队列。一个是进入监视器的等待队列一个是条件变量对应的等待队列。后者可以有多个。就像一个病人进入门诊室诊断后，需要去验血，那么它需要去抽血室排队等待。另外一个病人心脏不舒服，需要去拍胸片，去拍摄室等待。 6.监视器要求的条件满足后，位于条件变量下等待的线程需要重新在门诊室门外排队，等待进入监视器。就像抽血的那位，抽完后，拿到了化验单，然后，重新回到门诊室等待，然后进入看病，然后退出，医生通知下一位进入。</p><p>总结起来就是，管程就是一个对象监视器。任何线程想要访问该资源，就要排队进入监控范围。进入之后，接受检查，不符合条件，则要继续等待，直到被通知，然后继续进入监视器。2019-08-01密码123456 👍（148） 💬（9）有hasen 是执行完，再去唤醒另外一个线程。能够保证线程的执行。hoare，是中断当前线程，唤醒另外一个线程，执行玩再去唤醒，也能够保证完成。而mesa是进入等待队列，不一定有机会能够执行。2019-03-16三圆 👍（98） 💬（14）看了三遍，终于明白了管程MESA模型了，刚开始一直在想线程T1执行出队是什么意思？到底是哪个队列，是入口等待队列，还是条件等待队列，后来理解了都不是。这个队列应该理解为JDK里面的阻塞队列，里面存在的是共享数据，线程T1,T2分别去操作里面的共享数据，执行数据的入队，出队操作，当然这些操作是阻塞操作。当线程T1对阻塞队列执行数据出队操作时，进入管程，发现阻塞队列为空，此时线程T1进入阻塞队列不为空这个条件的条件等待队列，此时，其他线程还是可以进入管程的，比如T2进来了，对阻塞队列执行数据插入操作，这时就会致使线程T1从条件等待队列出来，进入入口等待队列，准备再一次进入管程……至于wait方法的参数，还是有必要的，因为可能线程需要的条件可能一直无法满足！2019-03-16Hour 👍（71） 💬（16）老师，针对条件变量的while循环，还是不太理解，您说是范式，那它一定是为了解决特定的场景而强烈推荐的，也有评论说是为了解决虚假唤醒，但唤醒后，不也是从条件的等待队列进入到入口的等待队列，抢到锁后，重新进行条件变量的判断，用if完全可以啊，为什么必须是while，并且是范式？</p><p>望老师赐教！2019-03-22linqw 👍（61） 💬（3）管程的组成锁和0或者多个条件变量，java用两种方式实现了管程①synchronized+wait、notify、notifyAll②lock+内部的condition，第一种只支持一个条件变量，即wait，调用wait时会将其加到等待队列中，被notify时，会随机通知一个线程加到获取锁的等待队列中，第二种相对第一种condition支持中断和增加了时间的等待，lock需要自己进行加锁解锁，更加灵活，两个都是可重入锁，但是lock支持公平和非公平锁，synchronized支持非公平锁，老师，不知道理解的对不对2019-04-07小李子 👍（47） 💬（5）wait() 不加超时参数，相当于得一直等着别人叫你去门口排队，加了超时参数，相当于等一段时间，再没人叫的话，我就受不了自己去门口排队了，这样就诊的机会会大一点，是这样理解吧？2019-04-05Geek_0quh3e 👍（37） 💬（6）老师，您好，结合第六讲，我的理解是：简单来说，一个锁实际上对应两个队列，一个是就绪队列，对应本节的入口等待队列，一个是阻塞队列，实际对应本节的条件变量等待队列，wait操作是把当前线程放入条件变量的等待队列中，而notifyall是将条件变量等待队列中的所有线程唤醒到就绪队列（入口等待队列）中，实际上哪个线程执行由jvm操作，我这样的理解对吗？2019-03-20CCC 👍（24） 💬（4）MESA模型和其他两种模型相比可以实现更好的公平性，因为唤醒只是把你放到队列里而不保证你一定可以执行，最后能不能执行还是要看你自己可不可以抢得到执行权也就是入口，其他两种模型是显式地唤醒，有点内定的意思了。2019-03-17长脖子树 👍（20） 💬（1）没有看懂的可以看下 coursera 上北京大学陈老师讲的课程 MESA 管程 https://www.coursera.org/lecture/os-pku/mesaguan-cheng-Fya0t2020-04-14红衣闪闪亮晶晶 👍（20） 💬（1）老师，我能明白如果t1线程被唤醒后再次进入等待队列，但是可能再次走到条件变量那里再次因为条件不满足随后再次开始等待，所以需要增加超时，所以当我给wait加了超时，时间到了以后t1再次开始while中的判断，如果满足便自己回到入口等待队列？ 我这样理解对吗？2019-03-26虎虎❤️ 👍（19） 💬（2）重新回答思考题，问题变成wait的timeout参数是否必要。</p><p>在MESA模型中，线程T1被唤醒，从条件A的等待队列中（其实是一个set，list的话可能会重复）移除，并加入入口等待队列，重新与其他的线程竞争锁的控制权。那么有这样一种可能，线程T1的优先级比较低，并且经常地有高优先级的线程加入入口等待队列。每次当它获得锁的时候，条件已经不满足了（被高优先级的线程抢先破坏了条件）。即使T1可以得到调度，但是也没办法继续执行下去。</p><p>最后T1被饿死了（有点冷。。。）</p><p>另外我刚才的问题想通了。不需要实现像lock一样的条件对象，并调用condition.await(). Synchronized用判断条件+wait（）就可以了。 2019-03-16Healtheon 👍（15） 💬（2）感谢老师的精彩分享，谈一下个人对信号量和管程的理解。</p><p>信号量机制是可以解决同步/互斥的问题的，但是信号量的操作分散在各个进程或线程中，不方便进行管理，因每次需调用PV操作，还可能导致死锁或破坏互斥请求的问题。</p><p>管程是定义了一个数据结构和能为并发所执行的一组操作，这组操作能够进行同步和改变管程中的数据。这相当于对临界资源的同步操作都集中进行管理，凡是要访问临界资源的进程或线程，都必须先通过管程，由管程的这套机制来实现多进程或线程对同一个临界资源的互斥访问和使用。管程的同步主要通过condition类型的变量（条件变量），条件变量可执行操作wait()和signal()。管程一般是由语言编译器进行封装，体现出OOP中的封装思想，也如老师所讲的，管程模型和面向对象高度契合的。2019-03-16Geek_6m7v5y 👍（14） 💬（2）老师，有个疑问，文中说到的条件变量，假如 synchronized(instance)｛做一些事情｝，这样一段代码，程序实际运行过程中条件变量是什么呢2019-03-23雷刚 👍（12） 💬（4）JUC AQS 就是这么实现的，它有两个队列，一个是同步队列，一个是等待队列：</p><ol><li>同步队列：锁被占用时，会将该线程添加到同步队列中。当锁释放后，会从队列中唤醒一个线程，又分为公平和非公平两种。</li><li>等待队列：当调用 await 是，会将该线程添加到等待队列中。当其它线程调用 notify 时，会将该线程从等待队列移动到同步队列中，重新竞争锁。</li></ol><p>后来又了解了一下 synchronized 的实现原理，ObjectMonitor 结构也差不多，原来这就是管程 MESA 模型，一切都套路，有章可循。 以前读源码，基本上是看什么忘什么，主要还是不了解代码背后的设计原理。如果了解原理后，这样不用看代码，基本上能猜出来是怎么实现的，以后还是要加强理论的学习。计算机理论的学习也非常枯燥，大家一起共勉。2020-03-18饮识止渴(Vilin) 👍（9） 💬（1）线程wait超时后，会重新被放入入口队列，去争取锁吗？2019-05-13</p>`,58)])])}const u=n(i,[["render",l]]);export{g as __pageData,u as default};
